(function () {
  if (window.__gsDisplayEmojiPolicy) return;
  window.__gsDisplayEmojiPolicy = true;
  var emoji = /\p{Extended_Pictographic}|\p{Regional_Indicator}|[\u{1F3FB}-\u{1F3FF}\u{E0020}-\u{E007F}\u200D\u20E3\uFE0E\uFE0F]/gu;
  function clean(value) { return value.replace(emoji, ''); }
  function scrub(node) {
    if (node.nodeType === 3) {
      var parent = node.parentElement;
      if (parent && parent.closest('script,style,textarea')) return;
      var text = clean(node.nodeValue || '');
      if (text !== node.nodeValue) node.nodeValue = text;
      return;
    }
    if (node.nodeType === 1) {
      if (/^(SCRIPT|STYLE|TEXTAREA)$/.test(node.tagName)) return;
      if (node.shadowRoot) watch(node.shadowRoot);
      ['title', 'aria-label', 'placeholder', 'alt'].forEach(function (name) {
        if (!node.hasAttribute(name)) return;
        var value = node.getAttribute(name);
        var safe = clean(value);
        if (safe !== value) node.setAttribute(name, safe);
      });
    }
    Array.prototype.forEach.call(node.childNodes || [], scrub);
  }
  var observed = new WeakSet();
  var observer = new MutationObserver(function (records) {
    records.forEach(function (record) {
      if (record.type === 'childList') Array.prototype.forEach.call(record.addedNodes, scrub);
      else scrub(record.target);
    });
  });
  function watch(root) {
    if (observed.has(root)) return;
    observed.add(root);
    observer.observe(root, { subtree: true, childList: true, characterData: true,
      attributes: true, attributeFilter: ['title', 'aria-label', 'placeholder', 'alt'] });
    scrub(root);
  }
  if (window.Element && Element.prototype.attachShadow) {
    var attachShadow = Element.prototype.attachShadow;
    Element.prototype.attachShadow = function (options) {
      var root = attachShadow.call(this, options);
      watch(root); // Closed roots must be observed before they become inaccessible.
      return root;
    };
  }
  [window.CanvasRenderingContext2D, window.OffscreenCanvasRenderingContext2D].forEach(function (type) {
    if (!type) return;
    ['fillText', 'strokeText'].forEach(function (name) {
      var original = type.prototype[name];
      if (!original) return;
      type.prototype[name] = function () {
        var args = Array.prototype.slice.call(arguments);
        if (typeof args[0] !== 'symbol') args[0] = clean(String(args[0]));
        return original.apply(this, args);
      };
    });
  });
  watch(document);
})();
